window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-63237770bab1372e"]={"versions": [{"id": "FIG-63237770bab1372e", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen AUTOSAR-Basissoftwaremodulen innerhalb der Kommunikationsarchitektur (Communication Stack). Das Diagramm stellt das Wiedereinschalten der Empfangs-Deadline-Überwachung (RX Deadline Monitoring) während des Bus-off-Wiederanlaufs (Bus-off Recovery) des CAN State Managers dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als <code>«module»</code> typisierte Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>Com::Com</code>: AUTOSAR Communication-Modul zur Signalverarbeitung und I-PDU-Deadline-Überwachung.</li>\n<li><code>CanSM::CanSM</code>: CAN State Manager zur Steuerung von Kommunikationszuständen und Bus-off-Behandlung.</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstelle:</p>\n<ul class=\"fig-list\">\n<li><code>Com_EnableReceptionDM(IpduGroupId := CANSM_RX_PDU_GROUP_ID)</code>: Synchrone C-Funktionsschnittstelle des COM-Moduls zur Reaktivierung des Empfangs-Deadline-Monitorings für eine konfigurierte I-PDU-Gruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf innerhalb des optionalen Fragments (<code>opt Disabling of RX Timeouts during bus off recovery</code>):</p>\n<ol class=\"fig-list\">\n<li>Ausführungsbedingung (Guard): <code>[CANSM_BOR_DISABLE_RX_DL_MONITORING == true]</code>.</li>\n<li><code>CanSM</code> ruft synchron <code>Com_EnableReceptionDM</code> mit dem Parameter <code>IpduGroupId := CANSM_RX_PDU_GROUP_ID</code> am Modul <code>Com</code> auf.</li>\n<li>Nach Ausführung der Funktion im <code>Com</code>-Modul kehrt der Kontrollfluss via gestrichelter Antwortnachricht (Return) zu <code>CanSM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf ist an den Vorkompilierungs- bzw. Konfigurationsschalter <code>CANSM_BOR_DISABLE_RX_DL_MONITORING</code> gekoppelt. Ist dieses Feature auf <code>true</code> konfiguriert, muss die CanSM-Zustandsmaschine beim Bus-off-Recovery-Prozess nach erfolgreichem Wiederanlauf sicherstellen, dass die während der Bus-off-Phase deaktivierte RX-Deadline-Überwachung der betreffenden CAN-PDU-Gruppe über den symbolischen Bezeichner <code>CANSM_RX_PDU_GROUP_ID</code> im COM-Stack wieder aktiviert wird.</p>"}, {"id": "FIG-c6a8428336e4f593", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen AUTOSAR-Basissoftwaremodulen innerhalb der Kommunikationsarchitektur (Communication Stack). Das Diagramm stellt das Wiedereinschalten der Empfangs-Deadline-Überwachung (RX Deadline Monitoring) während des Bus-off-Wiederanlaufs (Bus-off Recovery) des CAN State Managers dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten (als <code>«module»</code> typisierte Lebenslinien):</p>\n<ul class=\"fig-list\">\n<li><code>Com::Com</code>: AUTOSAR Communication-Modul zur Signalverarbeitung und I-PDU-Deadline-Überwachung.</li>\n<li><code>CanSM::CanSM</code>: CAN State Manager zur Steuerung von Kommunikationszuständen und Bus-off-Behandlung.</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstelle:</p>\n<ul class=\"fig-list\">\n<li><code>Com_EnableReceptionDM(IpduGroupId := CANSM_RX_PDU_GROUP_ID)</code>: Synchrone C-Funktionsschnittstelle des COM-Moduls zur Reaktivierung des Empfangs-Deadline-Monitorings für eine konfigurierte I-PDU-Gruppe.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ablauf innerhalb des optionalen Fragments (<code>opt Disabling of RX Timeouts during bus off recovery</code>):</p>\n<ol class=\"fig-list\">\n<li>Ausführungsbedingung (Guard): <code>[CANSM_BOR_DISABLE_RX_DL_MONITORING == true]</code>.</li>\n<li><code>CanSM</code> ruft synchron <code>Com_EnableReceptionDM</code> mit dem Parameter <code>IpduGroupId := CANSM_RX_PDU_GROUP_ID</code> am Modul <code>Com</code> auf.</li>\n<li>Nach Ausführung der Funktion im <code>Com</code>-Modul kehrt der Kontrollfluss via gestrichelter Antwortnachricht (Return) zu <code>CanSM</code> zurück.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf ist an den Vorkompilierungs- bzw. Konfigurationsschalter <code>CANSM_BOR_DISABLE_RX_DL_MONITORING</code> gekoppelt. Ist dieses Feature auf <code>true</code> konfiguriert, muss die CanSM-Zustandsmaschine beim Bus-off-Recovery-Prozess nach erfolgreichem Wiederanlauf sicherstellen, dass die während der Bus-off-Phase deaktivierte RX-Deadline-Überwachung der betreffenden CAN-PDU-Gruppe über den symbolischen Bezeichner <code>CANSM_RX_PDU_GROUP_ID</code> im COM-Stack wieder aktiviert wird.</p>"}], "trans": [{"from": "FIG-63237770bab1372e", "to": "FIG-c6a8428336e4f593", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
